var redNodes = require("./nodes");
var flows = require("./flows");
var storage = require("./storage");
var library = require("./library");
var plugins = require("./plugins");
var settings = require("./settings");
const multiplayer = require("./multiplayer");
const telemetry = require("./telemetry");
const coordination = require("./coordination");
const instanceState = require("./state");
const health = require("./health");
const readOnlyUserDir = require("./readOnlyUserDir");
const reloadWatcher = require("./flows/reload");
const httpHold = require("./httpHold");
const httpDrain = require("./httpDrain");
const {messageText} = require("./printable");

var express = require("express");
var path = require('path');
var fs = require("fs");
var os = require("os");
const crypto = require("crypto")

const {log,i18n,events,exec,util,hooks} = require("@node-red/util");

var runtimeMetricInterval = null;

var started = false;

var stubbedExpressApp = {
    get: function() {},
    post: function() {},
    put: function() {},
    delete: function() {}
}
var adminApi = {
    auth: {
        needsPermission: function() {return function(req,res,next) {next()}},
        publicRoute: function() {return function(req,res,next) {next()}}
    },
    adminApp: stubbedExpressApp,
    server: {}
}

var nodeApp;
var adminApp;
var server;
let userSettings;
// Z-11: settings overridden by readOnlyUserDir (logged at start), or null
let readOnlyOverrides = null;

// #71: the largest delay of a Node.js timer - a larger one fires after 1 ms
const MAX_STARTUP_TIMEOUT = 2147483647;
// #71: the text used when a value cannot be converted to a string
const NOT_PRINTABLE = "(the value cannot be printed)";
