        abandonAttempt(attempt, "timeout", function() {
            const step = attempt.step;
            const err = new Error(log._("runtime.startup-timeout", {timeout: timeout, step: step}));
            err.code = "startup_timeout";
            err.step = step;
            err.timeout = timeout;
            return err;
        });
