    if (!settings.available()) {
        return false;
    }
    if (Object.prototype.hasOwnProperty.call(userSettings, 'instanceId') && userSettings.instanceId === undefined) {
        // the accessor of the runtime settings reads localSettings[key], so it stays valid
        delete userSettings.instanceId;
    }
    let instanceId = settings.get('instanceId');
    const generated = instanceId === undefined;
    if (generated) {
        instanceId = crypto.randomBytes(8).toString('hex');
        try {
            await settings.set('instanceId', instanceId);
        } catch (err) {
            log.warn(log._("runtime.instance-id-save-failed", {message: messageText(err)}));
        }
    }
